import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineBulkDiscount, invoiceTotals } from './invoices.js';

export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customer = customerResult.value;

  const lines = [];

  lines.push(invoice.number || 'DRAFT');
  lines.push(customer.name);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceText = formatEuros(line.unitPrice);
    const totalText = formatEuros(total);
    lines.push(`${line.qty} ${line.name} ${unitPriceText} ${totalText}`);

    const regularDiscount = lineDiscount(line);
    const bulkDiscount = lineBulkDiscount(line);
    const totalDiscount = regularDiscount + bulkDiscount;
    if (totalDiscount > 0) {
      const discountText = formatEuros(totalDiscount);
      lines.push(`  Discount: ${discountText}`);
    }
  }

  const totals = invoiceTotals(invoice);

  if (totals.voucher > 0) {
    const voucherText = formatEuros(totals.voucher);
    lines.push(`Voucher: ${voucherText}`);
  }

  const vatText = formatEuros(totals.vat);
  lines.push(`VAT: ${vatText}`);

  const totalText = formatEuros(totals.total);
  lines.push(`Total: ${totalText}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    const paidText = formatEuros(totalPaid);
    lines.push(`Paid: ${paidText}`);
  }

  return lines.join('\n');
}

