import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders a draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 5,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const text = renderInvoiceText(invoice);

  assert(text.includes('DRAFT'));
  assert(text.includes('Northwind Studio'));
  assert(text.includes('5 Development (hour) €95.00 €475.00'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
